package com.marketplace.adapters.in.web.category;
import com.marketplace.application.category.CategoryUseCase; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/categories") public class CategoryController { private final CategoryUseCase useCase; public CategoryController(CategoryUseCase u){useCase=u;} @GetMapping public List<CategoryUseCase.View> list(){return useCase.list();} @GetMapping("/{id}") public CategoryUseCase.View get(@PathVariable Long id){return useCase.get(id);} @PostMapping public ResponseEntity<CategoryUseCase.View> create(@Valid @RequestBody CategoryRequest r){var c=useCase.create(new CategoryUseCase.Command(r.name(),r.description(),r.active()==null||r.active()));return ResponseEntity.created(URI.create("/api/categories/"+c.id())).body(c);}@PutMapping("/{id}") public CategoryUseCase.View update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return useCase.update(id,new CategoryUseCase.Command(r.name(),r.description(),r.active()==null||r.active()));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){useCase.deactivate(id);} }
